    case "ON_FAULT_TRACK_ON":
      return "Hardware fault signal detected. Track still running but fault may escalate. Inspect PSU.";
    case "ON_TRACK_OFF_NO_FAULT":
      return "Track is shut down with no PSU fault signal detected. Unexpected shutdown — verify control inputs and physical track state.";
    case "ON_STUD_FAULT_TRACK_ON":
      return "Stud faults detected. PSU operating normally and track running. Schedule stud inspection.";
    case "ON_STUD_FAULT_TRACK_OFF":
      return "Track is shut down and stud faults detected. No PSU fault — investigate track state and stud health.";
    case "ON_OK":
      return "PSU online, track running, no faults detected. System operating normally.";

    // STALE
    case "ST_FAULT_OR_TRACK_OFF":
      return "Communication degrading. Last known state indicates track shut down and/or fault signal active. Prioritize investigation.";
    case "ST_STUD_FAULT":
      return "Communication degrading. Stud faults reported at last heartbeat. Monitor comms and stud health.";
    case "ST_NO_FAULT":
      return "Communication gap detected. No hardware faults at last heartbeat. Device typically self-recovers. Wait before acting.";

    // OFFLINE
    case "OFF_FAULT":
      return "Communication lost. Last known state: hardware fault confirmed. Technician required.";
    case "OFF_STUD_FAULT_TRACK_OFF":
      return "Communication lost. Last known state: track shut down and stud faults active. Check connectivity and stud health.";
    case "OFF_STUD_FAULT":
      return "Communication lost. Last known state: stud faults detected. Investigate stud health and connectivity.";
    case "OFF_TRACK_OFF_NO_FAULT":
      return "Communication lost. Last known state: track was shut down with no fault signal. Verify control inputs and connectivity before dispatching.";
    case "OFF_LONG_NO_FAULT":
      return "Extended communication loss with no hardware fault at last heartbeat. Check connectivity and signal quality before dispatching.";
    case "OFF_SHORT_NO_FAULT":
      return "Communication lost with no hardware fault detected at last heartbeat. Likely signal issue. Continue monitoring.";

    default:
      return code || "-";
  }

