markerImage.imageFunction:
// Marker Image Function
// Returns custom colored marker based on tunnel status

// Get the max action level for this tunnel
var maxActionLevel = 0;

// Check if we have maxActionLevel data
if (data && data.maxActionLevel !== undefined && data.maxActionLevel !== null) {
    maxActionLevel = Number(data.maxActionLevel);
}

// Determine marker color based on action level
var markerColor = '#808080'; // Default gray (unknown)

if (maxActionLevel === 0) {
    markerColor = '#4CAF50'; // Green - Healthy
} else if (maxActionLevel === 1) {
    markerColor = '#FFEB3B'; // Yellow - Monitor
} else if (maxActionLevel === 2) {
    markerColor = '#FF9800'; // Orange - Investigate
} else if (maxActionLevel >= 3) {
    markerColor = '#F44336'; // Red - Critical
}

// Create custom SVG marker (location pin shape)
var svgMarker = 
    '<svg width="32" height="48" viewBox="0 0 32 48" xmlns="http://www.w3.org/2000/svg">' +
    '<defs>' +
    '<filter id="shadow" x="-50%" y="-50%" width="200%" height="200%">' +
    '<feDropShadow dx="0" dy="2" stdDeviation="2" flood-opacity="0.3"/>' +
    '</filter>' +
    '</defs>' +
    // Main pin shape
    '<path d="M16 0C7.2 0 0 7.2 0 16c0 12 16 32 16 32s16-20 16-32c0-8.8-7.2-16-16-16z" ' +
    'fill="' + markerColor + '" stroke="#fff" stroke-width="2" filter="url(#shadow)"/>' +
    // Inner circle
    '<circle cx="16" cy="16" r="7" fill="#fff" opacity="0.9"/>' +
    // Status indicator (smaller circle)
    '<circle cx="16" cy="16" r="4" fill="' + markerColor + '"/>' +
    '</svg>';

// Return marker configuration
return {
    url: 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent(svgMarker),
    size: [32, 48],
    anchor: [16, 48]
};

